Definition rg_post (f : frw) (s : Z) (r r' : bvmap 5 word) : Prop :=
  getr r' 2 = Z_to_bv 64 s /\ getr r' 1 = f_ret f /\
  getr r' 8 = f_v0 f /\ getr r' 9 = f_v1 f /\ getr r' 18 = f_v2 f /\ getr r' 19 = f_v3 f /\ getr r' 20 = f_v4 f /\ getr r' 21 = f_v5 f /\
  getr r' 22 = f_v6 f /\ getr r' 23 = f_v7 f /\ getr r' 24 = f_v8 f /\ getr r' 25 = f_v9 f /\ getr r' 26 = f_v10 f /\ getr r' 27 = f_v11 f /\
  getr r' 3 = getr r 3 /\ getr r' 4 = getr r 4.

Lemma rg_post_agree : forall f s (r0 r r' : bvmap 5 word),
  rg_post f s r r' -> getr r 3 = getr r0 3 -> getr r 4 = getr r0 4 -> rg_post f s r0 r'.
